-- ============================================================
-- v20 演示数据扩充：客户 / 联系人 / 商机 / 订单 / 应收 / 收款 / 发货
--      / 报价 / 退换货 / 工单 / 回访 / 公海 / 线索 / 跟进
-- 生成器：Spring Boot/sql/gen_demo_dataset.py（随机种子固定，可重跑）
-- 幂等：批次表 crm_seed_batches 记录 v20_demo_dataset，重复执行直接跳过
-- ============================================================

CREATE TABLE IF NOT EXISTS crm_seed_batches (
  name varchar(60) NOT NULL PRIMARY KEY,
  applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  note varchar(200) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP PROCEDURE IF EXISTS seed_v20_demo;
DELIMITER $$
CREATE PROCEDURE seed_v20_demo()
BEGIN
  IF EXISTS (SELECT 1 FROM crm_seed_batches WHERE name='v20_demo_dataset') THEN
    SELECT 'skip: v20_demo_dataset 已执行过' AS result;
  ELSE
      '客户+56 联系人+85 商机+55 订单+218 明细+616 应收+210 收款+233 发货+194 报价+70 退换货+26 工单+78 回访+72 公海+22 线索+150 跟进+188');
  END IF;
END$$
DELIMITER ;

CALL seed_v20_demo();
DROP PROCEDURE seed_v20_demo;

-- 执行后的体量核对
SELECT 'customers' AS 表, COUNT(*) AS 行数 FROM crm_customers
UNION ALL SELECT 'orders', COUNT(*) FROM crm_orders
UNION ALL SELECT 'order_items', COUNT(*) FROM crm_order_items
UNION ALL SELECT 'opportunities', COUNT(*) FROM crm_opportunities
UNION ALL SELECT 'clues', COUNT(*) FROM crm_clues
UNION ALL SELECT module_name, COUNT(*) FROM crm_module_records GROUP BY module_name;
